def evaluate(current_reputation: float, observation: dict, my_history: list[dict], round_num: int) -> float:
    # Asymmetric learning: punish defection more heavily than reward donation
    if observation['action'] == 'donate':
        step = 0.1  # gentle positive update
    else:
        step = 0.3  # strong negative update

    # Exponential moving average toward +/-1
    target = 1.0 if observation['action'] == 'donate' else -1.0
    new_rep = current_reputation + step * (target - current_reputation)

    # Clamp to allowed range
    return max(-1.0, min(1.0, new_rep))


