def decide(recipient_reputation: float, round_num: int, my_history: list[dict]) -> bool:
    # Check recent defections against us (as recipient) in the last 3 rounds.
    recent_defections = 0
    last_entries = my_history[-3:]
    for entry in last_entries:
        if entry.get("role") == "recipient" and entry["partner_action"] == "not_donate":
            recent_defections += 1
    # If we have been defected against recently, withhold cooperation unless reputation is very high.
    if recent_defections > 0:
        # Forgive only if recipient has excellent reputation.
        return recipient_reputation >= 0.8
    # Otherwise, base decision on general reputation.
    return recipient_reputation >= 0.3
